// Lógica do nó "Decidir" do fluxo "eLabFTW – Checagem de consistência".
// Função pura: recebe os recursos e experimentos completos (GET /items/{id}, GET /experiments/{id}) e os usuários;
// devolve um pedido de e-mail por destinatário (líder do projeto ou dono de registro solto) e, se configurado, o consolidado.
// Só aponta pendências; não altera nada.

const DIA = 24 * 3600e3;

function campos(x) {
  let m = x.metadata_decoded || x.metadata;
  if (typeof m === 'string') {
    try { m = JSON.parse(m); } catch (e) { m = {}; }
  }
  return (m && m.extra_fields) || {};
}

function valor(x, nome) {
  const c = campos(x)[nome];
  return c && c.value !== undefined && c.value !== null ? String(c.value).trim() : '';
}

function ligados(x, categorias) {
  const ids = new Map();
  for (const l of [...(x.items_links || []), ...(x.related_items_links || []),
    ...(x.experiments_links || []), ...(x.related_experiments_links || [])]) {
    if (l && categorias.includes(l.category_title)) ids.set(`${l.category_title}:${l.entityid}`, l);
  }
  return [...ids.values()];
}

function decidirChecagem({ recursos, experimentos, usuarios, hoje, cfg }) {
  const usuario = new Map(usuarios.filter((u) => u && u.userid !== undefined).map((u) => [String(u.userid), u]));
  const testador = usuario.get(String(cfg.usuarioTesteId));
  if (cfg.modoTeste && !(testador && testador.email)) {
    throw new Error(`Modo de teste: usuário ${cfg.usuarioTesteId} sem e-mail legível pela API; nada foi enviado.`);
  }
  const c = cfg.categorias;
  const url = (tipo, id) => `${cfg.urlPublica}/${tipo === 'exp' ? 'experiments' : 'database'}.php?mode=view&id=${id}`;
  const itens = recursos.filter((x) => x && x.id !== undefined).map((x) => ({ ...x, _tipo: 'item' }));
  const exps = experimentos.filter((x) => x && x.id !== undefined).map((x) => ({ ...x, _tipo: 'exp' }));
  const todos = [...itens, ...exps];

  const fichas = new Map(itens.filter((x) => x.category_title === c.ficha).map((f) => [String(f.id), f]));
  const ativa = (f, ampla) => f && (f.status_title === cfg.situacaoAndamento || (ampla && f.status_title === cfg.situacaoPlanejamento));
  const fichasDe = (x) => ligados(x, [c.ficha]).map((l) => fichas.get(String(l.entityid))).filter(Boolean);

  const porFicha = new Map(); // id da ficha -> lista de pendências
  const soltos = new Map(); // userid -> lista de pendências
  const anotar = (f, texto, x) => {
    const k = String(f.id);
    porFicha.set(k, [...(porFicha.get(k) || []), { texto, url: url(x._tipo, x.id) }]);
  };
  const deFichasAtivas = (x, ampla) => fichasDe(x).filter((f) => ativa(f, ampla));

  const categoriasRegistro = [c.plano, c.caderno, c.desvio, c.marco, c.evidencia, c.produto];
  for (const x of todos) {
    if (!categoriasRegistro.includes(x.category_title)) continue;
    if (fichasDe(x).length === 0) {
      const k = String(x.userid);
      soltos.set(k, [...(soltos.get(k) || []), { texto: `${x.category_title} sem ligação com a ficha do projeto: "${x.title}"`, url: url(x._tipo, x.id) }]);
    }
  }

  for (const f of fichas.values()) {
    if (!ativa(f, false)) continue;
    const planos = exps.filter((x) => x.category_title === c.plano && fichasDe(x).some((g) => g.id === f.id));
    if (planos.length === 0) anotar(f, 'O projeto não tem plano de pesquisa ligado à ficha', f);
    for (const p of planos) {
      const faltam = (p.steps || []).filter((s) => !Number(s.finished) && !/^\s*\(desej[áa]vel\)/i.test(s.body || ''));
      if (faltam.length) anotar(f, `Plano "${p.title}": itens da lista de verificação não marcados: ${faltam.map((s) => s.body).join('; ')}`, p);
    }
    const termino = valor(f, cfg.campoTermino);
    if (termino && new Date(`${termino}T23:59:59${cfg.fuso}`) < hoje) {
      anotar(f, `O término previsto (${termino.split('-').reverse().join('/')}) já passou e o projeto continua "${cfg.situacaoAndamento}": atualize a data ou a situação`, f);
    }
  }

  for (const x of todos) {
    if (x.category_title === c.evidencia) {
      const semLocal = !valor(x, cfg.campoLocalizacao) && !(x.uploads || []).length;
      if (semLocal) for (const f of deFichasAtivas(x, true)) anotar(f, `Evidência "${x.title}" sem localização e sem anexo`, x);
    } else if (x.category_title === c.produto) {
      if (valor(x, cfg.campoSituacaoProduto) === cfg.produtoPublicado && !valor(x, cfg.campoDoi)) {
        for (const f of deFichasAtivas(x, true)) anotar(f, `Produto "${x.title}" publicado sem DOI ou endereço`, x);
      }
    } else if (x.category_title === c.caderno) {
      if (ligados(x, [c.evidencia]).length === 0) {
        for (const f of deFichasAtivas(x, false)) anotar(f, `Entrada de caderno "${x.title}" sem evidência ligada`, x);
      }
    }
  }

  const dezembro = hoje.getMonth() + 1 === cfg.mesPreChecagem;
  const intro = dezembro
    ? `Esta é a pré-checagem do relatório anual de PD&I, que será gerado em 15 de janeiro. Corrija as pendências abaixo até lá, para o relatório sair completo.`
    : 'A conferência periódica do eLabFTW encontrou as pendências abaixo, comparando os registros com os mínimos das Diretrizes de Pesquisa Aplicada.';
  const saida = [];
  const consolidado = [];

  function pedido(userid, titulo, blocos, nomeProjeto) {
    const pessoa = usuario.get(String(userid));
    const real = pessoa && pessoa.email ? pessoa.email : '';
    const nome = (pessoa && pessoa.fullname) || 'pesquisador(a)';
    const b = [{ tipo: 'paragrafo', texto: `Olá, ${nome}.` }, { tipo: 'paragrafo', texto: intro }, ...blocos,
      { tipo: 'paragrafo', texto: 'Esta mensagem só aponta; nada foi alterado. Em caso de dúvida sobre algum item, consulte as Diretrizes ou responda a este e-mail.' }];
    if (cfg.modoTeste) b.push({ tipo: 'aviso', tom: 'atencao', texto: `Modo de teste: este e-mail iria para ${nome}${real ? ` (${real})` : ' (sem e-mail)'}.` });
    const para = cfg.modoTeste ? testador.email : real;
    if (!para) return { acao: 'sem-destinatario', userid: Number(userid), projeto: nomeProjeto || '' };
    return {
      acao: 'enviar',
      para,
      nomeRemetente: 'PD&I Modal',
      responderPara: 'pesquisa@modal.org.br',
      assunto: `${cfg.modoTeste ? '[TESTE] ' : ''}eLabFTW: ${titulo}`,
      etiqueta: dezembro ? 'eLabFTW · Pré-checagem do relatório anual' : 'eLabFTW · Conferência dos registros',
      titulo,
      blocos: b,
      acaoRotulo: 'Abrir o eLabFTW',
      acaoUrl: cfg.urlPublica,
      rodape: 'Conferência automática do eLabFTW do Modal. Dúvidas: pesquisa@modal.org.br.',
    };
  }

  // um e-mail por líder, com uma seção por projeto
  const porLider = new Map();
  for (const [fid, lista] of porFicha) {
    const f = fichas.get(fid);
    const k = String(f.userid);
    porLider.set(k, [...(porLider.get(k) || []), { f, lista }]);
  }
  for (const [userid, projetos] of porLider) {
    const total = projetos.reduce((n, p) => n + p.lista.length, 0);
    const blocos = projetos.flatMap(({ f, lista }) => [
      { tipo: 'subtitulo', texto: f.title },
      { tipo: 'lista', itens: lista },
      { tipo: 'botoes', itens: [{ rotulo: 'Abrir a ficha do projeto', url: url('item', f.id) }] },
    ]);
    const titulo = projetos.length === 1
      ? `${total} pendência(s) no projeto "${projetos[0].f.title}"`
      : `${total} pendência(s) em ${projetos.length} projetos`;
    saida.push(pedido(userid, titulo, blocos, projetos.map((p) => p.f.title).join('; ')));
    for (const { f, lista } of projetos) consolidado.push({ rotulo: f.title, lista });
  }
  for (const [userid, lista] of soltos) {
    saida.push(pedido(userid, `${lista.length} registro(s) sem ligação com projeto`, [
      { tipo: 'paragrafo', texto: 'Sem a ligação com a ficha, o registro não aparece no projeto nem no relatório anual. Abra cada registro e, na seção Links, ligue-o à ficha do projeto.' },
      { tipo: 'lista', itens: lista },
    ]));
    const pessoa = usuario.get(userid);
    consolidado.push({ rotulo: `Registros sem projeto de ${(pessoa && pessoa.fullname) || `usuário ${userid}`}`, lista });
  }

  if (cfg.copiaPara && consolidado.length) {
    const total = consolidado.reduce((n, g) => n + g.lista.length, 0);
    saida.push({
      acao: 'enviar',
      para: cfg.modoTeste ? testador.email : cfg.copiaPara,
      nomeRemetente: 'PD&I Modal',
      assunto: `${cfg.modoTeste ? '[TESTE] ' : ''}eLabFTW: consolidado da conferência (${total} pendência(s))`,
      etiqueta: dezembro ? 'eLabFTW · Pré-checagem do relatório anual' : 'eLabFTW · Conferência dos registros',
      titulo: `Consolidado: ${total} pendência(s) em ${consolidado.length} grupo(s)`,
      blocos: [
        { tipo: 'paragrafo', texto: 'Cópia do que foi enviado a cada pesquisador-líder e aos donos de registros sem projeto.' },
        ...consolidado.flatMap((g) => [{ tipo: 'subtitulo', texto: g.rotulo }, { tipo: 'lista', itens: g.lista }]),
        ...(cfg.modoTeste ? [{ tipo: 'aviso', tom: 'atencao', texto: `Modo de teste: este consolidado iria para ${cfg.copiaPara}.` }] : []),
      ],
      acaoRotulo: 'Abrir o eLabFTW',
      acaoUrl: cfg.urlPublica,
      rodape: 'Conferência automática do eLabFTW do Modal.',
    });
  }
  return saida;
}


const dados = (nome) => $(nome).all().map((i) => i.json);
const saida = decidirChecagem({
  recursos: dados('Ler recurso completo'),
  experimentos: dados('Ler experimento completo'),
  usuarios: dados('Ler usuários'),
  hoje: new Date(),
  cfg: $('Configuração').first().json,
});
return saida.map((json) => ({ json }));

